import React, { useState } from "react";
import Modal from "react-modal";
import { CgCloseR } from "react-icons/cg";
import { useTranslation } from "react-i18next";

const ServiceArea = () => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const { t } = useTranslation();

    // Obtener el título y las regiones desde el JSON de traducciones
    const serviceAreaData: { title?: string; region?: string }[] = t("serviceArea", { returnObjects: true });
    const title = serviceAreaData[0]?.title || "ZONE DE SERVICE";
    const regions = serviceAreaData.slice(1).map(item => item.region);

    return (
        <>
            <button onClick={() => setIsModalOpen(true)} className="bg-primary text-accent px-4 py-2 rounded">
                Voir la zone de service
            </button>
            <Modal
                isOpen={isModalOpen}
                onRequestClose={() => setIsModalOpen(false)}
                className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50"
                overlayClassName="fixed inset-0"
                >
                <div className="bg-primary text-neutral p-6 rounded-lg shadow-lg max-w-lg w-full relative">
                    <button onClick={() => setIsModalOpen(false)} className="absolute top-2 right-2 text-gray-600 hover:text-gray-900 text-2xl">
                        <CgCloseR className="text-neutral" />
                    </button>
                    <h2 className="text-3xl font-bold text-center mb-4">{title}</h2>
                    <ul className="list-disc list-inside ml-12">
                        {regions.map((region, index) => (
                            <li key={index} className="text-2xl text-secondary">{region}</li>
                        ))}
                    </ul>
                </div>
            </Modal>
        </>
    );
};

export default ServiceArea;
