import React, { ReactNode, useEffect, useState } from "react";
import { UserProfile } from "../interfaces";
import Navigation from "../components/nav";
import LanguageSelector from "./languageSelector";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { SiInstagram } from "react-icons/si";
import { ImFacebook2 } from "react-icons/im";
import {
  FaSquareFacebook,
  FaSquarePhone,
  FaSquareWhatsapp,
} from "react-icons/fa6";
import { MdEmail } from "react-icons/md";
import images from "../images";
import data from "../data/data.json";
import { motion, AnimatePresence } from "framer-motion";
import { Link, useLocation } from "@reach/router";
import ServiceArea from "./serviceArea";

interface LayoutProps {
  children: ReactNode;
  data?: UserProfile;
}

interface FooterData {
  copy: string;
}

const userData: UserProfile = data;

const pageVariants = {
  initial: {
    opacity: 0,
    x: "100%",
  },
  in: {
    opacity: 1,
    x: 0,
    transition: {
      duration: 0.6,
      ease: "easeInOut",
    },
  },
  out: {
    opacity: 0,
    x: "-100%",
    transition: {
      duration: 0.6,
      ease: "easeInOut",
    },
  },
};

const Layout: React.FC<LayoutProps> = ({ children, data }) => {
  const { t } = useTranslation();
  const [currentPath, setCurrentPath] = useState("");
  const location = typeof window !== "undefined" ? useLocation() : null;
  const [currentYear, setYear] = useState<number | null>(null);

  React.useEffect(() => {
    setYear(new Date().getFullYear());
  }, []);

  function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `+1 ${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
        4,
        7
      )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }

  useEffect(() => {
    if (location) {
      setCurrentPath(location.pathname);
    }
  }, [location]);

  return (
    <>
      <div
        className="fixed inset-0 bg-no-repeat bg-cover bg-center before:content-[''] before:absolute before:inset-0 before:bg-white/10"
        style={{ backgroundImage: `url(${images.flooring_background.src})` }}
      ></div>
      <div id={data?.menu[0]} className={styles.container}>
        <div className={styles.header}>
          <Link to="/" className={styles.logoContainer}> 
            <img
              src={images.logo.src}
              alt={images.logo.alt}
              className={styles.logo}
            />
          </Link>
          <Navigation data={data} />
          <LanguageSelector data={data} />
        </div>
        <AnimatePresence mode="wait">
          <motion.div
            key={currentPath || "default"}
            initial="initial"
            animate="in"
            exit="out"
            variants={pageVariants}
            className="relative"
          >
            {children}
          </motion.div>
        </AnimatePresence>        
      </div>

      <footer className={styles.footerContainer} id={userData.menu[4]}>
        <div className="flex flex-col sm:flex-row">
          <div className="flex flex-col self-center w-full py-8 justify-center items-center">
            <img
              className="mx-auto w-1/3 shadow-2xl"
              src={images.logo_simple.src}
              alt={images.logo_simple.src}
            />
            <div className="flex justify-center mt-4">
              <ServiceArea />
            </div>
            <a href={data?.facebook} target="_blank" rel="noreferrer">
                <ImFacebook2 className="text-terciary text-3xl mt-4" />
              </a>
          </div>

          <div className="flex flex-col w-full self-center">
            <h3 className="mx-auto text-3xl text-center font-extrabold">{data?.name}</h3>
            <h4 className="mx-auto text-3xl text-center font-extrabold">{data?.rbq}</h4>
            <p className="mx-auto text-2xl text-center">{data?.address}</p>
            <p className="mx-auto text-2xl text-center">{data?.city}, {data?.province}, {data?.postalCode}</p>
            <a
              href={`mailto:${data?.email}`}
              className="flex flex-row gap-2 justify-center items-center text-lg sm:text-xl"
            >
              <MdEmail />
              {data?.email}
            </a>
            <a
              href={`tel:${data?.phone}`}
              className="flex flex-row gap-2 justify-center items-center text-xl"
            >
              <FaSquarePhone />
              {formatPhoneNumber(data?.phone || "")}
            </a>
          </div>

        </div>
          <div className="flex flex-col self-center text-center w-full">
            {/* <div className="flex mt-2 mx-auto justify-center sm:mx-0 gap-4">
              <a href={data?.instagram} target="_blank" rel="noreferrer">
                <SiInstagram className="text-terciary text-4xl" />
              </a>
              <a href={data?.facebook} target="_blank" rel="noreferrer">
                <ImFacebook2 className="text-terciary text-4xl" />
              </a>
            </div> */}
            <div className="mx-auto p-4">
              &copy; {currentYear} {data?.name}
            </div>
          </div>
      </footer>
    </>
  );
};

export default Layout;

const styles = {
  container: "pt-4 mx-auto",
  header: "flex flex-row justify-center items-center px-4 sm:px-0",
  footerContainer: "bg-accent-600 text-neutral flex flex-col text-light relative",
  logoContainer:
    "flex justify-center items-center shadow-2xl relative",
  logo: "w-64 sm:w-[22rem] h-auto",
  number: "absolute text-error text-shadow text-xl sm:text-2xl -bottom-5 sm:-bottom-4 right-1 z-10",
};
